package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
public final class AppearanceChoices{
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Appearance & Motion").setMessage(String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage())).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout panel,JSONObject player){button(a,panel,player,true);button(a,panel,player,false);EquipmentEditor.attach(a,panel,player);}
 private static void button(Activity a,LinearLayout panel,JSONObject player,boolean skin){Button b=new Button(a);b.setText(skin?"Skin · Game palettes":"Celebration IDs");b.setAllCaps(false);b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject req=new JSONObject(player.toString()).put("section",skin?"skin":"celebration");JSONObject data=new JSONObject(manage(a,"ui78_appearance_get",req));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing()){if(skin)SkinColourEditor.form(a,player,data);else form(a,player,data,false);}});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"AppearanceChoicesLoad").start();});panel.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private static Spinner select(Activity a,LinearLayout col,String title,String[] labels,int selected){TextView t=new TextView(a);t.setText(title);t.setTextColor(0xffe4efff);t.setPadding(0,16,0,8);col.addView(t);Spinner s=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);s.setSelection(Math.max(0,selected));col.addView(s,new LinearLayout.LayoutParams(-1,-2));return s;}
 private static int[] ids(JSONArray rows){int[] out=new int[rows.length()];for(int i=0;i<out.length;i++)out[i]=rows.optJSONObject(i).optInt("id");return out;}
 private static String[] names(JSONArray rows,int current){String[] out=new String[rows.length()];for(int i=0;i<out.length;i++){JSONObject r=rows.optJSONObject(i);JSONArray cards=r.optJSONArray("cards");JSONObject c=cards==null?null:cards.optJSONObject(0);out[i]=String.format(Locale.US,"%04d",r.optInt("id"))+(r.optInt("id")==current?" · Current":"")+(c==null?"":" · "+c.optString("name")+" · "+c.optString("id"));}return out;}
 private static int position(int[] ids,int current){for(int i=0;i<ids.length;i++)if(ids[i]==current)return i;return 0;}
 private static void form(Activity a,JSONObject player,JSONObject data,boolean skin){LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=Math.round(16*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);col.setBackgroundColor(0xff101f38);ScrollView scroll=new ScrollView(a);scroll.addView(col);TextView note=new TextView(a);note.setTextColor(0xffc9dfee);col.addView(note);final Spinner palette,goal,memorial;final int[] gi,mi;
 if(skin){note.setText("Uses native body-skin palettes1–6. Original restores the game's own selection. Face textures keep their own coloring; this does not recolor the face. Use the custom RGB editor to choose an exact colour.");palette=select(a,col,"Body skin palette",new String[]{"Original","Palette1","Palette2","Palette3","Palette4","Palette5","Palette6"},data.optInt("skin"));goal=null;memorial=null;gi=null;mi=null;}
 else{note.setText("Select IDs stored in the card's actual game parameters. Main and Memorial use separate ID tables. These IDs are not animation filenames. Close and reopen the app after saving before entering a match.");JSONObject choices=data.optJSONObject("choices");JSONArray g=choices.optJSONArray("59"),m=choices.optJSONArray("60");gi=ids(g);mi=ids(m);goal=select(a,col,"Main · Current ID "+data.optInt("59"),names(g,data.optInt("59")),position(gi,data.optInt("59")));memorial=select(a,col,"Memorial · Current ID "+data.optInt("60"),names(m,data.optInt("60")),position(mi,data.optInt("60")));palette=null;}
 AlertDialog d=new AlertDialog.Builder(a).setTitle(skin?"Skin · Game palettes":"Celebration IDs").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONObject values=new JSONObject().put("59",skin?data.optInt("59"):gi[goal.getSelectedItemPosition()]).put("60",skin?data.optInt("60"):mi[memorial.getSelectedItemPosition()]);int sk=skin?palette.getSelectedItemPosition():data.optInt("skin");if(sk>0)values.put("skin",sk);JSONObject req=new JSONObject(player.toString()).put("values",values);d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject result=new JSONObject(manage(a,"ui78_appearance_apply",req));if(!result.optBoolean("saved"))throw new Exception("Save was not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen the app before entering a match.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"AppearanceChoicesSave").start();}catch(Exception e){error(a,e);}});
 }
}
